function majorityElement(nums) {
  let cand = null
  let count = 0
  for (const x of nums) {
    if (count === 0) cand = x
    count += x === cand ? 1 : -1
  }
  let seen = 0
  for (const x of nums) if (x === cand) seen++
  return seen > nums.length / 2 ? cand : null
}

