function findAll(text, pattern) {
  const m = pattern.length
  if (m === 0) return []
  const lps = [0]
  let k = 0
  for (let i = 1; i < m; i++) {
    while (k && pattern[i] !== pattern[k]) k = lps[k - 1]
    if (pattern[i] === pattern[k]) k++
    lps.push(k)
  }
  const out = []
  k = 0
  for (let i = 0; i < text.length; i++) {
    while (k && text[i] !== pattern[k]) k = lps[k - 1]
    if (text[i] === pattern[k]) k++
    if (k === m) {
      out.push(i - m + 1)
      k = lps[k - 1]
    }
  }
  return out
}

