function largestRectangle(heights) {
  const bars = [...heights, 0]
  const st = []
  let best = 0
  for (let i = 0; i < bars.length; i++) {
    while (st.length && bars[st[st.length - 1]] > bars[i]) {
      const h = bars[st.pop()]
      const left = st.length ? st[st.length - 1] : -1
      best = Math.max(best, h * (i - left - 1))
    }
    st.push(i)
  }
  return best
}
